"use client";

import { type CommandPaletteProps, CommandPalette as CommandPaletteRoot } from "./command-palette";
import {
  CommandPaletteContent,
  type CommandPaletteContentProps,
  type CommandPaletteDensity,
  type CommandPaletteFrame,
  commandPaletteContentVariants,
} from "./command-palette-content";
import { CommandPaletteCount, type CommandPaletteCountProps } from "./command-palette-count";
import { CommandPaletteEmpty, type CommandPaletteEmptyProps } from "./command-palette-empty";
import { CommandPaletteFooter, type CommandPaletteFooterProps } from "./command-palette-footer";
import { CommandPaletteGroup, type CommandPaletteGroupProps } from "./command-palette-group";
import { CommandPaletteInput, type CommandPaletteInputProps } from "./command-palette-input";
import {
  CommandPaletteItem,
  type CommandPaletteItemProps,
  type CommandPaletteItemTone,
} from "./command-palette-item";
import { CommandPaletteList, type CommandPaletteListProps } from "./command-palette-list";

const CommandPalette = Object.assign(CommandPaletteRoot, {
  Content: CommandPaletteContent,
  Input: CommandPaletteInput,
  Count: CommandPaletteCount,
  List: CommandPaletteList,
  Group: CommandPaletteGroup,
  Item: CommandPaletteItem,
  Empty: CommandPaletteEmpty,
  Footer: CommandPaletteFooter,
});

export { CommandPalette, type CommandPaletteProps };
export {
  CommandPaletteContent,
  commandPaletteContentVariants,
  type CommandPaletteContentProps,
  type CommandPaletteFrame,
  type CommandPaletteDensity,
};
export { CommandPaletteInput, type CommandPaletteInputProps };
export { CommandPaletteList, type CommandPaletteListProps };
export { CommandPaletteGroup, type CommandPaletteGroupProps };
export { CommandPaletteItem, type CommandPaletteItemProps, type CommandPaletteItemTone };
export { CommandPaletteEmpty, type CommandPaletteEmptyProps };
export { CommandPaletteFooter, type CommandPaletteFooterProps };
export { CommandPaletteCount, type CommandPaletteCountProps };

"use client";

import type { ReactNode } from "react";
import { CommandPaletteContext } from "./command-palette-context";
import {
  type UseCommandPaletteStateOptions,
  useCommandPaletteState,
} from "./use-command-palette-state";

/** Props for command palette. */
export interface CommandPaletteProps extends UseCommandPaletteStateOptions {
  /** Content rendered inside the component. */
  children: ReactNode;
}

/**
 * Terminal-styled command palette with built-in search filtering, grouped items, and keyboard
 * navigation. Uses native dialog element with backdrop blur. Two orthogonal visual axes on
 * Content (frame and density) keep visual chrome configurable without touching internals.
 */
export function CommandPalette({ children, ...stateProps }: CommandPaletteProps) {
  const contextValue = useCommandPaletteState(stateProps);

  return <CommandPaletteContext value={contextValue}>{children}</CommandPaletteContext>;
}

"use client";

import { createContext, useContext } from "react";
import type { CommandPaletteContextValue } from "./use-command-palette-state";

export type { CommandPaletteContextValue } from "./use-command-palette-state";

export const CommandPaletteContext = createContext<CommandPaletteContextValue | undefined>(
  undefined,
);

export function useCommandPaletteContext() {
  const context = useContext(CommandPaletteContext);
  if (!context)
    throw new Error("CommandPalette compound components must be used within a CommandPalette");
  return context;
}

"use client";

import { cva, type VariantProps } from "class-variance-authority";
import { type ReactNode, useCallback, useRef, useState } from "react";
import { useFocusRestore } from "@/hooks/use-focus-restore";
import { useScrollLock } from "@/hooks/use-scroll-lock";
import { cn } from "@/lib/utils";
import { DialogShell } from "../shared/dialog-shell";
import { PortalContainerProvider } from "../shared/portal-context";
import { useCommandPaletteContext } from "./command-palette-context";

/** Allowed command palette frame values. */
export type CommandPaletteFrame = "border" | "viewfinder" | "terminal" | "card" | "none";
/** Allowed command palette density values. */
export type CommandPaletteDensity = "compact" | "comfortable" | "dense";

/** Class variants for command palette content. */
export const commandPaletteContentVariants = cva(
  cn(
    "relative flex flex-col max-h-[80dvh] w-full font-mono",
    // Top-pinned, not centred: the software keyboard shrinks the visual viewport
    // the instant the user starts typing, and a centred panel jumps upward at
    // exactly the wrong moment. A fixed top edge holds the input row still for
    // the whole session. max() degrades to 12px without viewport-fit=cover.
    "mx-auto mt-[max(0.75rem,env(safe-area-inset-top))] mb-auto",
    // Narrow viewports: inset from the edge so both vertical hairlines and the
    // offset shadow stay on-screen. At >=640px the size variants still rule.
    "max-sm:mx-3 max-sm:w-[calc(100%-1.5rem)] max-sm:max-w-none",
  ),
  {
    variants: {
      size: { sm: "max-w-sm", md: "max-w-xl", lg: "max-w-2xl" },
    },
    defaultVariants: { size: "md" },
  },
);

function getLiveText(search: string, itemCount: number): string {
  if (!search) return "";
  if (itemCount === 0) return "No results";
  return `${itemCount} result${itemCount === 1 ? "" : "s"} available`;
}

/** Props for command palette content. */
export interface CommandPaletteContentProps
  extends VariantProps<typeof commandPaletteContentVariants> {
  /** Content rendered inside the component. */
  children: ReactNode;
  /** Additional class names merged onto the rendered element. */
  className?: string;
  /** Accessible name for the modal dialog. */
  label?: string;
  /**
   * Shell chrome style. "border" renders a 1px hairline. "viewfinder" renders four corner
   * brackets with no border plus a 2px left accent bar on the selected row. "terminal" renders
   * top + bottom 2px rules with inverted selection and swaps the default prefix glyph from > to
   * $. "card" renders an 8px rounded shell with a subtle gradient surface and a floating
   * rounded selection (compose with a search-icon `prefix` for the Linear look). "none" is a
   * bare shell for embedding.
   */
  frame?: CommandPaletteFrame | null;
  /**
   * Typographic and spacing surface. Switches a token block (--command-palette-row-h,
   * --command-palette-input-py, --command-palette-list-p, --command-palette-text-size, etc.)
   * consumed by every inner slot via [data-density] selectors in
   * command-palette/command-palette.css. "compact" matches the V1 refined-mono target,
   * "comfortable" is Linear-ish breathing room, "dense" is VSCode-tight.
   */
  density?: CommandPaletteDensity | null;
  /**
   * Renders the palette as a modal dialog in the browser top layer (default). Pass false to
   * render it in the document flow instead — an embedded palette with the same frame, density,
   * and highlight chrome, without a backdrop, focus trap, or focus restoration. Inline palettes
   * still honour `open`, so they unmount when the consumer closes them.
   */
  modal?: boolean;
}

/** Modal (or embedded) palette container with frame + density variants. */
export function CommandPaletteContent({
  children,
  className,
  size,
  frame,
  density,
  modal = true,
  label = "Command palette",
}: CommandPaletteContentProps) {
  const { open, onOpenChange, search, onSearchChange, itemCount, inputRef } =
    useCommandPaletteContext();
  const shellRef = useRef<HTMLDialogElement>(null);
  const scrollLockTargetRef = useRef<HTMLElement>(null);
  const [container, setContainer] = useState<Element | null>(null);
  const focusRestore = useFocusRestore({ restoreOnUnmount: true });
  useScrollLock({ target: scrollLockTargetRef, enabled: open && modal });

  const resolvedFrame = frame ?? "border";
  const resolvedDensity = density ?? "compact";

  // Stable identity for DialogShell's dialogRef callback so the underlying ref isn't re-attached on every render.
  const setDialogRef = useCallback((node: HTMLDialogElement | null) => {
    shellRef.current = node;
    scrollLockTargetRef.current = node?.ownerDocument.body ?? null;
    setContainer(node);
  }, []);

  // Stable identity for DialogShell's onAfterShowModal so focus runs only on open transitions.
  const focusSearchInput = useCallback(() => {
    inputRef.current?.focus();
  }, [inputRef]);

  // Not memoized: useFocusRestore hands back a fresh object every render, so a
  // useCallback keyed on it could never hit. DialogShell does not need a stable
  // identity here either.
  const handleClose = () => {
    const view = shellRef.current?.ownerDocument.defaultView ?? globalThis;
    view.requestAnimationFrame(() => {
      focusRestore.restore();
    });
  };

  const inner = (
    <PortalContainerProvider container={container}>
      {resolvedFrame === "viewfinder" ? <span aria-hidden="true" className="cp-corners" /> : null}
      {children}
      {/* biome-ignore lint/a11y/useSemanticElements: role="status" is the sr-only results-count live region; <output> carries form-association semantics that do not fit here. */}
      <div role="status" aria-live="polite" aria-atomic="true" className="sr-only">
        {getLiveText(search, itemCount)}
      </div>
    </PortalContainerProvider>
  );

  if (!modal) {
    if (!open) return null;
    return (
      // biome-ignore lint/a11y/useSemanticElements: <fieldset> is a form-control grouping element; this is a labelled composite region wrapping a combobox and its listbox, so role="group" on a div is the correct mapping.
      <div
        // Inline mode has no dialog element; the shell itself is the portal container.
        ref={setContainer}
        role="group"
        aria-label={label}
        data-slot="command-palette-content"
        data-frame={resolvedFrame}
        data-density={resolvedDensity}
        data-state="open"
        className={cn(commandPaletteContentVariants({ size }), className)}
      >
        {inner}
      </div>
    );
  }

  return (
    <DialogShell
      open={open}
      dialogRef={setDialogRef}
      onBeforeShowModal={focusRestore.capture}
      onAfterShowModal={focusSearchInput}
      onBackdropClick={() => onOpenChange(false)}
      onCancel={() => (search ? onSearchChange("") : onOpenChange(false))}
      onExitComplete={handleClose}
      className={cn(commandPaletteContentVariants({ size }), className)}
      data-slot="command-palette-content"
      data-frame={resolvedFrame}
      data-density={resolvedDensity}
      aria-modal="true"
      aria-label={label}
    >
      {inner}
    </DialogShell>
  );
}

"use client";

import type { KeyboardEvent as ReactKeyboardEvent, ReactNode, Ref } from "react";
import { useComposedRefs } from "@/hooks/use-composed-refs";
import { Kbd } from "../kbd/kbd";
import { useCommandPaletteContext } from "./command-palette-context";
import { CommandPaletteCount } from "./command-palette-count";
import { getCommandPaletteItemDomId } from "./use-command-palette-state";

const INPUT_NAVIGATION_KEYS = new Set(["ArrowUp", "ArrowDown", "Enter"]);

/** Props for command palette input. */
export interface CommandPaletteInputProps {
  /** Search input placeholder. */
  placeholder?: string;
  /** Accessible label text. */
  label?: string;
  /**
   * Optional leading content. When omitted, a CSS-driven glyph from
   * --command-palette-prefix-content is rendered (default ">"; terminal frame swaps to "$").
   */
  prefix?: ReactNode;
  /** Optional trailing content. Defaults to the `[n/m]` count readout plus an Esc close button. */
  suffix?: ReactNode;
  /** Accessible name for the default Esc close control. */
  closeLabel?: string;
  /** Called when key down occurs. */
  onKeyDown?: (event: ReactKeyboardEvent<HTMLInputElement>) => void;
  /** Additional class names merged onto the rendered element. */
  className?: string;
  /** Ref forwarded to the underlying element. */
  ref?: Ref<HTMLInputElement>;
}

/** Search input with prefix/suffix slots (Esc Kbd by default) */
export function CommandPaletteInput({
  placeholder = "Type a command…",
  label = "Command search",
  prefix,
  suffix,
  closeLabel = "Close",
  onKeyDown,
  className,
  ref,
}: CommandPaletteInputProps) {
  const { open, onOpenChange, search, onSearchChange, navKeyDown, highlighted, listId, inputRef } =
    useCommandPaletteContext();
  const composedRef = useComposedRefs(inputRef, ref);

  return (
    <div data-slot="command-palette-input" className={className}>
      {prefix !== undefined ? (
        <span data-slot="command-palette-input-prefix">{prefix}</span>
      ) : (
        <span data-slot="command-palette-input-prefix" data-default aria-hidden="true" />
      )}
      <input
        ref={composedRef}
        type="text"
        role="combobox"
        aria-label={label}
        aria-expanded={open}
        aria-autocomplete="list"
        aria-controls={listId}
        aria-activedescendant={
          highlighted !== null ? getCommandPaletteItemDomId(listId, highlighted) : undefined
        }
        value={search}
        onChange={(e) => onSearchChange(e.target.value)}
        onKeyDown={(e) => {
          onKeyDown?.(e);
          if (e.defaultPrevented) return;
          if (e.nativeEvent.isComposing || e.keyCode === 229) return;
          if (e.key === "Escape") {
            if (search) {
              e.preventDefault();
              onSearchChange("");
            }
            return;
          }
          if (e.key === " ") return;
          if (INPUT_NAVIGATION_KEYS.has(e.key)) navKeyDown(e);
        }}
        placeholder={placeholder}
        className="flex-1 min-w-0 bg-transparent border-0 outline-none p-0 text-foreground placeholder-muted-foreground/70 font-mono caret-foreground"
      />
      {suffix !== undefined ? (
        <span data-slot="command-palette-input-suffix">{suffix}</span>
      ) : (
        <span data-slot="command-palette-input-suffix">
          <CommandPaletteCount />
          {/* A real close control, not a hint: touch has no Esc key, and the
              ::before hit-area expansion in command-palette.css gives it a 44x44
              target without moving a single desktop pixel. */}
          <button
            type="button"
            data-slot="command-palette-close"
            aria-label={closeLabel}
            onClick={() => onOpenChange(false)}
          >
            <Kbd size="sm">Esc</Kbd>
          </button>
        </span>
      )}
    </div>
  );
}

"use client";

import type { ComponentPropsWithRef } from "react";
import { useCommandPaletteContext } from "./command-palette-context";

/** Props for command palette count. The readout owns its own content. */
export type CommandPaletteCountProps = Omit<ComponentPropsWithRef<"span">, "children">;

/**
 * Bracketed position readout for the filtered list — `[3/24]` when a row is
 * highlighted, `[24]` when none is, `[0]` when the filter matched nothing.
 *
 * The palette already computes this for its live region; without the readout a
 * sighted keyboard user cannot tell whether the filter matched six rows or sixty
 * without scrolling. It is `aria-hidden` on purpose: the polite live region owns
 * the announcement, so screen-reader users hear it once, not twice.
 */
export function CommandPaletteCount({ className, ref, ...props }: CommandPaletteCountProps) {
  const { itemCount, highlightedPosition } = useCommandPaletteContext();
  const isEmpty = itemCount === 0;
  const position = !isEmpty && highlightedPosition !== null ? `${highlightedPosition}/` : "";

  return (
    <span
      {...props}
      ref={ref}
      data-slot="command-palette-count"
      data-empty={isEmpty ? "" : undefined}
      aria-hidden="true"
      className={className}
    >
      [{position}
      {itemCount}]
    </span>
  );
}

"use client";

import type { ComponentPropsWithRef, ReactNode } from "react";
import { useComposedRefs } from "@/hooks/use-composed-refs";
import { cn } from "@/lib/utils";
import { useCommandPaletteContext } from "./command-palette-context";

/** Props for command palette list. */
export interface CommandPaletteListProps
  extends Omit<ComponentPropsWithRef<"div">, "children" | "role" | "id"> {
  /** Content rendered inside the component. */
  children: ReactNode;
  /** Accessible name when no visible label is supplied. */
  "aria-label"?: string;
}

/** Scrollable item container. */
export function CommandPaletteList({
  children,
  className,
  "aria-label": ariaLabel = "Command results",
  ref,
  ...props
}: CommandPaletteListProps) {
  const { listRef, listId } = useCommandPaletteContext();
  const composedRef = useComposedRefs(listRef, ref);
  return (
    <div
      {...props}
      id={listId}
      ref={composedRef}
      role="listbox"
      aria-label={ariaLabel}
      data-slot="command-palette-list"
      className={cn("flex-1 overflow-y-auto overscroll-contain", className)}
    >
      {children}
    </div>
  );
}

"use client";

import { type ComponentPropsWithRef, type ReactNode, useId } from "react";
import { cn } from "@/lib/utils";

/** Props for command palette group. */
export interface CommandPaletteGroupProps
  extends Omit<ComponentPropsWithRef<"div">, "children" | "role" | "aria-labelledby"> {
  /** Group heading rendered above the items. */
  heading: ReactNode;
  /** Content rendered inside the component. */
  children: ReactNode;
}

/** Labeled group of items. */
export function CommandPaletteGroup({
  heading,
  children,
  className,
  ...props
}: CommandPaletteGroupProps) {
  const headingId = useId();
  return (
    // biome-ignore lint/a11y/useSemanticElements: role="group" labels a related set of command options; <fieldset> is for form controls and is not appropriate here.
    <div
      {...props}
      role="group"
      aria-labelledby={headingId}
      data-slot="command-palette-group"
      className={cn("hidden has-[[role=option]]:block", className)}
    >
      <div id={headingId} data-slot="command-palette-group-heading">
        {heading}
      </div>
      <div>{children}</div>
    </div>
  );
}

"use client";

import type { ComponentPropsWithRef, ReactNode } from "react";
import { useCommandPaletteContext } from "./command-palette-context";

/** Props for command palette empty. */
export interface CommandPaletteEmptyProps
  extends Omit<ComponentPropsWithRef<"div">, "children" | "role"> {
  /** Content rendered inside the component. */
  children: ReactNode;
}

/** Shown when no items match search. */
export function CommandPaletteEmpty({ children, className, ...props }: CommandPaletteEmptyProps) {
  const { itemCount, search } = useCommandPaletteContext();
  if (itemCount > 0 || !search) return null;
  return (
    // The no-results announcement is owned by CommandPaletteContent's single live
    // region; this presentational node is just the visible empty-state copy and
    // must not be an invalid live-region child of the listbox.
    <div {...props} role="presentation" data-slot="command-palette-empty" className={className}>
      {children}
    </div>
  );
}

"use client";

import type { ComponentPropsWithRef, ReactNode } from "react";
import { OverlayHints } from "../shared/overlay-hints";

/** Props for command palette footer. */
export interface CommandPaletteFooterProps extends ComponentPropsWithRef<"div"> {
  /**
   * Footer content. Omit it to render the palette's canonical keyboard legend
   * (Navigate / Select / Close) through the shared OverlayHints primitive.
   */
  children?: ReactNode;
}

/** Hint bar / status area. */
export function CommandPaletteFooter({ children, className, ...props }: CommandPaletteFooterProps) {
  return (
    <div {...props} data-slot="command-palette-footer" className={className}>
      {children ?? <DefaultHints />}
    </div>
  );
}

function DefaultHints() {
  return (
    <OverlayHints>
      <OverlayHints.Item keys={["↑", "↓"]} size="sm">
        Navigate
      </OverlayHints.Item>
      <OverlayHints.Item keys={["↵"]} size="sm">
        Select
      </OverlayHints.Item>
      <OverlayHints.Item keys={["Esc"]} size="sm">
        Close
      </OverlayHints.Item>
    </OverlayHints>
  );
}

"use client";

import {
  type ComponentPropsWithRef,
  type MouseEvent,
  type ReactNode,
  useId,
  useLayoutEffect,
  useRef,
} from "react";
import { useComposedRefs } from "@/hooks/use-composed-refs";
import { useCommandPaletteContext } from "./command-palette-context";
import { getCommandPaletteItemDomId } from "./use-command-palette-state";

/** Allowed command palette item tone values. */
export type CommandPaletteItemTone =
  | "neutral"
  | "nav"
  | "action"
  | "settings"
  | "destructive"
  | "ai";

/** Props for command palette item. */
export interface CommandPaletteItemProps
  extends Omit<ComponentPropsWithRef<"div">, "children" | "id" | "onSelect"> {
  /** Stable unique id used for highlight state and aria-activedescendant. */
  id: string;
  /** Searchable text. Defaults to id when omitted. */
  value?: string;
  /** Optional leading icon. Inherits tone color when a non-neutral tone is set. */
  icon?: ReactNode;
  /** Keyboard shortcut hint rendered next to the label. */
  shortcut?: string;
  /**
   * Semantic tone. Renders a 2px left bar and tints the optional icon via [data-tone]
   * selectors. The label color stays inherited so contrast holds under any frame. Map:
   * nav→info, action→success, settings→warning, destructive→destructive, ai→accent.
   */
  tone?: CommandPaletteItemTone;
  /** Called when the item is activated. Runs before CommandPalette.onActivate. */
  onSelect?: () => void;
  /** Disable activation and skip in keyboard navigation. */
  disabled?: boolean;
  /** Content rendered inside the component. */
  children: ReactNode;
}

/** Selectable item with icon, shortcut, tone, value. */
export function CommandPaletteItem({
  id,
  value,
  icon,
  shortcut,
  tone = "neutral",
  onSelect,
  disabled = false,
  children,
  className,
  ref,
  onClick,
  onMouseMove,
  ...props
}: CommandPaletteItemProps) {
  const {
    highlighted,
    onHighlightChange,
    onActivate,
    search,
    shouldFilter,
    filter,
    listId,
    registerItem,
    unregisterItem,
  } = useCommandPaletteContext();
  const registrationId = useId();
  const rootRef = useRef<HTMLDivElement>(null);
  const composedRef = useComposedRefs(rootRef, ref);

  const searchValue = value ?? id;
  const isVisible = !shouldFilter || !search || filter(searchValue, search);

  useLayoutEffect(() => {
    registerItem({
      registrationId,
      id,
      disabled: disabled || !isVisible,
      onSelect: disabled ? undefined : onSelect,
      element: isVisible ? rootRef.current : null,
    });
    return () => unregisterItem(registrationId);
  }, [disabled, id, isVisible, onSelect, registerItem, registrationId, unregisterItem]);

  if (!isVisible) return null;

  const isHighlighted = highlighted === id;

  const handleClick = (event: MouseEvent<HTMLDivElement>) => {
    onClick?.(event);
    if (!event.defaultPrevented && !disabled) onActivate(id);
  };

  const handleMouseMove = (event: MouseEvent<HTMLDivElement>) => {
    onMouseMove?.(event);
    if (event.defaultPrevented || disabled) return;
    if (highlighted !== id) onHighlightChange(id);
  };

  return (
    // biome-ignore lint/a11y/useFocusableInteractive: WAI-ARIA combobox/listbox pattern — option stays non-focusable while the input keeps focus and aria-activedescendant tracks the active option.
    // biome-ignore lint/a11y/useKeyWithClickEvents: Enter activation is handled centrally by the command palette input, not per option.
    <div
      {...props}
      ref={composedRef}
      id={getCommandPaletteItemDomId(listId, id)}
      role="option"
      data-slot="command-palette-item"
      data-value={id}
      data-tone={tone}
      data-highlighted={isHighlighted ? "" : undefined}
      aria-selected={isHighlighted}
      aria-disabled={disabled || undefined}
      onClick={handleClick}
      onMouseMove={handleMouseMove}
      className={className}
    >
      {icon !== undefined && <span data-slot="command-palette-item-icon">{icon}</span>}
      <span data-slot="command-palette-item-label">{children}</span>
      {shortcut ? <span data-slot="command-palette-item-shortcut">{shortcut}</span> : null}
    </div>
  );
}

"use client";

import { Children, type ReactNode } from "react";
import { foldSearchValue } from "@/lib/search";
import { useCommandPaletteContext } from "./command-palette-context";
import {
  CommandPaletteItem,
  type CommandPaletteItemProps,
  type CommandPaletteItemTone,
} from "./command-palette-item";

const TONE_RULES: ReadonlyArray<readonly [RegExp, CommandPaletteItemTone]> = [
  [/^(delete|remove|reset|drop|destroy|log\s*out|sign\s*out)\b/i, "destructive"],
  [/^(go to|open|jump|navigate|switch|view)\b/i, "nav"],
  [/^(toggle|enable|disable|set|configure|preferences|settings)\b/i, "settings"],
  [/^(ask|generate|summari[sz]e|explain|chat|ai)\b/i, "ai"],
  [/^(run|exec|build|test|deploy|create|new|add|export|import|copy)\b/i, "action"],
];

export function categorize(value: string): CommandPaletteItemTone {
  const trimmed = value.trim();
  for (const [pattern, tone] of TONE_RULES) {
    if (pattern.test(trimmed)) return tone;
  }
  return "neutral";
}

// Grapheme clusters, not code points: a <mark> boundary must never split a
// surrogate pair or detach a combining mark from its base letter. Array.from
// is the code-point fallback where Intl.Segmenter is unavailable.
const graphemeSegmenter =
  typeof Intl.Segmenter === "function"
    ? new Intl.Segmenter(undefined, { granularity: "grapheme" })
    : null;

function splitGraphemes(value: string): string[] {
  if (!graphemeSegmenter) return Array.from(value);
  return Array.from(graphemeSegmenter.segment(value), (segment) => segment.segment);
}

function buildFoldIndexMap(graphemes: readonly string[]): { folded: string; indexMap: number[] } {
  const indexMap: number[] = [];
  let folded = "";
  for (let i = 0; i < graphemes.length; i++) {
    const foldedGrapheme = foldSearchValue(graphemes[i] ?? "");
    for (let j = 0; j < foldedGrapheme.length; j++) {
      indexMap.push(i);
    }
    folded += foldedGrapheme;
  }
  return { folded, indexMap };
}

export function matchPositions(value: string, search: string): number[] {
  if (!search) return [];
  const graphemes = splitGraphemes(value);
  const { folded: foldedValue, indexMap } = buildFoldIndexMap(graphemes);
  const foldedSearch = foldSearchValue(search);
  const contiguous = foldedValue.indexOf(foldedSearch);
  if (contiguous !== -1) {
    const positions = new Set<number>();
    for (let i = contiguous; i < contiguous + foldedSearch.length; i++) {
      positions.add(indexMap[i] ?? 0);
    }
    return [...positions].sort((a, b) => a - b);
  }
  const positions: number[] = [];
  let cursor = 0;
  for (const char of foldedSearch) {
    const index = foldedValue.indexOf(char, cursor);
    if (index === -1) return [];
    positions.push(indexMap[index] ?? 0);
    cursor = index + 1;
  }
  return positions;
}

function renderWithMatches(value: string, search: string): ReactNode {
  const graphemes = splitGraphemes(value);
  const positions = matchPositions(value, search);
  if (positions.length === 0) return value;
  const set = new Set(positions);
  const nodes: ReactNode[] = [];
  let index = 0;
  // Emit one node per run, not per grapheme: labels re-render on every keystroke,
  // and adjacent single-character marks are announced once each by screen readers.
  while (index < graphemes.length) {
    const isMatch = set.has(index);
    let end = index;
    while (end < graphemes.length && set.has(end) === isMatch) end++;
    const run = graphemes.slice(index, end).join("");
    if (isMatch) {
      nodes.push(
        <mark key={index} data-slot="command-palette-item-match">
          {run}
        </mark>,
      );
    } else {
      nodes.push(run);
    }
    index = end;
  }
  return nodes;
}

function extractText(children: ReactNode): string {
  let text = "";
  Children.forEach(children, (child) => {
    if (typeof child === "string" || typeof child === "number") {
      text += String(child);
    }
  });
  return text;
}

// Children are highlight-safe when extractText recovers the full descendant
// text — i.e. nothing was dropped by skipping non-string nodes. For mixed
// content (icons, <strong>, etc.) we must render children untouched to avoid
// silent content loss.
function isPureText(children: ReactNode): boolean {
  if (typeof children === "string" || typeof children === "number") return true;
  if (Array.isArray(children)) return children.every(isPureText);
  return false;
}

/** Props for command palette highlight item. */
export interface CommandPaletteHighlightItemProps extends Omit<CommandPaletteItemProps, "tone"> {
  /** Visual tone. */
  tone?: CommandPaletteItemTone;
  /** Accessible label text. */
  label?: string;
}

export function CommandPaletteHighlightItem({
  tone,
  value,
  label,
  children,
  "aria-label": ariaLabel,
  ...rest
}: CommandPaletteHighlightItemProps) {
  const { search } = useCommandPaletteContext();
  const renderedChildren = children ?? label;
  const childrenIsPureText = children !== undefined && isPureText(children);
  const labelText = label ?? (childrenIsPureText ? extractText(children) : undefined);
  const searchValue = value ?? (labelText || undefined);
  const resolvedTone = tone ?? categorize(labelText ?? "");
  return (
    <CommandPaletteItem
      {...rest}
      value={searchValue}
      tone={resolvedTone}
      aria-label={ariaLabel ?? label}
    >
      {childrenIsPureText && search
        ? renderWithMatches(extractText(children), search)
        : renderedChildren}
    </CommandPaletteItem>
  );
}

